+import { describe, it, expect, vi, beforeEach } from 'vitest';
+
+/* eslint-disable @typescript-eslint/no-explicit-any */
+
+// Capture the arguments passed to streamText so we can inspect the system prompt
+let capturedStreamTextArgs: any = null;
+
+// Mock the 'ai' module — streamText is the main function we need to intercept
+vi.mock('ai', () => ({
+  smoothStream: vi.fn(() => vi.fn()),
+  streamText: vi.fn(async (args: any) => {
+    capturedStreamTextArgs = args;
+    return {
+      toDataStreamResponse: vi.fn(() => new Response('ok', { status: 200 }))
+    };
+  }),
+  tool: vi.fn((config: any) => config)
+}));
+
+// Mock AI model providers
+vi.mock('@ai-sdk/openai', () => ({
+  openai: vi.fn(() => 'mock-openai-model')
+}));
+
+vi.mock('@/lib/ai/google', () => ({
+  google: vi.fn(() => 'mock-google-model')
+}));
+
+// Mock the tools — we don't need real tool implementations
+vi.mock('@/tools', () => ({
+  createPanelTool: { name: 'createPanel' },
+  generateImageTool: { name: 'generateImage' },
+  createTextTool: { name: 'createText' }
+}));
+
+// Mock logger
+vi.mock('@/lib/logger', () => ({
+  default: vi.fn(() => ({
+    error: vi.fn(),
+    info: vi.fn(),
+    warn: vi.fn()
+  }))
+}));
+
+// Mock the base model lookup
+vi.mock('@/data/base-model', () => ({
+  getBaseModelByFileName: vi.fn(async () => ({
+    tokenCost: 10
+  }))
+}));
+
+// Mock Prisma (used for AiTool tag lookups)
+vi.mock('@/lib/prisma', () => ({
+  default: {
+    tag: {
+      findMany: vi.fn(async () => [])
+    }
+  }
+}));
+
+// Mock AiTool data layer
+vi.mock('@/data/ai-tool', () => ({
+  getAiToolsForPrompt: vi.fn(async () => [])
+}));
+
+// Mock constants that the route handler now imports
+vi.mock('@/constants/chat', () => ({
+  CANVAS_CHAT_TOOL_NAMES: ['createPanel', 'generateImage', 'createText'],
+  MAX_SUGGESTED_AI_TOOLS: 5
+}));
+
+vi.mock('@/constants/image-generation', () => ({
+  DEFAULT_BASE_MODEL: 'test-model'
+}));
+
+import { POST } from '@/app/api/chat/route';
+
+/**
+ * Helper to create a minimal Request object for calling the POST handler.
+ */
+function createChatRequest(body: Record<string, any>): Request {
+  return new Request('http://localhost:3000/api/chat', {
+    method: 'POST',
+    headers: { 'Content-Type': 'application/json' },
+    body: JSON.stringify(body)
+  });
+}
+
+/**
+ * Extracts the system message content from the captured streamText arguments.
+ */
+function getSystemPromptContent(): string {
+  expect(capturedStreamTextArgs).not.toBeNull();
+  const messages = capturedStreamTextArgs.messages;
+  expect(messages).toBeDefined();
+  expect(messages.length).toBeGreaterThan(0);
+
+  const systemMessage = messages.find(
+    (m: any) => m.role === 'system'
+  );
+  expect(systemMessage).toBeDefined();
+  return systemMessage.content as string;
+}
+
+describe('Chat API - System Prompt: Reference Image Guidance', () => {
+  beforeEach(() => {
+    vi.clearAllMocks();
+    capturedStreamTextArgs = null;
+  });
+
+  it('should include reference image guidance in the system prompt', async () => {
+    const req = createChatRequest({
+      messages: [{ role: 'user', content: 'Hello' }]
+    });
+
+    await POST(req);
+
+    const systemPrompt = getSystemPromptContent();
+
+    // The system prompt should contain guidance about reference images
+    // being automatically used when the user attaches them
+    expect(systemPrompt).toContain('reference image');
+  });
+
+  it('should instruct the AI about the useReferenceImages parameter', async () => {
+    const req = createChatRequest({
+      messages: [{ role: 'user', content: 'Hello' }]
+    });
+
+    await POST(req);
+
+    const systemPrompt = getSystemPromptContent();
+
+    // The system prompt should mention the useReferenceImages parameter
+    // so the AI knows how to control it
+    expect(systemPrompt).toContain('useReferenceImages');
+  });
+
+  it('should explain the default behavior is to use reference images', async () => {
+    const req = createChatRequest({
+      messages: [{ role: 'user', content: 'Hello' }]
+    });
+
+    await POST(req);
+
+    const systemPrompt = getSystemPromptContent();
+
+    // The default should be to USE reference images (opt-out model)
+    // The prompt should say to set useReferenceImages to false only
+    // when the user explicitly requests text-only generation
+    expect(systemPrompt).toContain('useReferenceImages');
+    expect(systemPrompt).toMatch(/false.*when.*explicit/i);
+  });
+});
