+import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest';
+import { render, screen, act } from '@testing-library/react';
+import { NextIntlClientProvider } from 'next-intl';
+
+import type { ChatAttachment } from '@/lib/chat-image-utils';
+import type { CanvasObject } from '@/components/canvas/types';
+
+// ---------------------------------------------------------------------------
+// Mock stores and modules BEFORE importing the component
+// ---------------------------------------------------------------------------
+
+// Keep a mutable reference to "selected" so tests can control it
+let mockSelected: Array<{ id: string; type: string }> = [];
+let mockCanvasObjects: CanvasObject[] = [];
+
+vi.mock('@/store/selection-store', () => ({
+  useSelectionStore: vi.fn((selector: (state: unknown) => unknown) => {
+    const state = {
+      selection: { selected: mockSelected },
+      removeFromSelection: vi.fn(),
+    };
+    return selector(state);
+  }),
+}));
+
+// Also expose getState for the effect that calls useSelectionStore.getState()
+const mockGetState = vi.fn(() => ({
+  selection: { selected: mockSelected },
+}));
+
+// Patch the module after mock so getState works
+import { useSelectionStore } from '@/store/selection-store';
+(useSelectionStore as unknown as { getState: typeof mockGetState }).getState =
+  mockGetState;
+
+vi.mock('@/store/canvas-store', () => ({
+  useCanvasStore: vi.fn((selector: (state: unknown) => unknown) => {
+    const state = { canvasObjects: mockCanvasObjects };
+    return selector(state);
+  }),
+}));
+
+vi.mock('sonner', () => ({
+  toast: { error: vi.fn(), success: vi.fn() },
+}));
+
+// Mock the child ChatImageAttachmentArea to simplify rendering and to expose
+// the attachment count so we can assert indirectly.
+vi.mock(
+  '@/app/[locale]/(canvas)/canvas/[id]/_components/chat-image-attachment-area',
+  () => ({
+    ChatImageAttachmentArea: ({
+      attachments,
+    }: {
+      attachments: ChatAttachment[];
+      onRemove: (id: string) => void;
+    }) => (
+      <div data-testid="attachment-area" data-count={attachments.length}>
+        {attachments.map((a) => (
+          <span key={a.id} data-testid={`attachment-${a.id}`}>
+            {a.name}
+          </span>
+        ))}
+      </div>
+    ),
+  })
+);
+
+// Mock chat-image-utils partially – keep the real constant and types
+vi.mock('@/lib/chat-image-utils', async () => {
+  const actual = await vi.importActual<typeof import('@/lib/chat-image-utils')>(
+    '@/lib/chat-image-utils'
+  );
+  return {
+    ...actual,
+    // buildCanvasAttachmentsFromSelection: create attachments from selection
+    buildCanvasAttachmentsFromSelection: (
+      selectionItems: Array<{ id: string; type: string }>,
+      _canvasObjects: CanvasObject[],
+      currentAttachments: ChatAttachment[]
+    ) => {
+      // Simulate: keep uploads from current, add canvas items for image selections
+      const uploads = currentAttachments.filter((a) => a.source === 'upload');
+      const canvasAttachments: ChatAttachment[] = selectionItems
+        .filter((s) => s.type === 'image')
+        .map((s) => ({
+          id: s.id,
+          name: `Canvas image ${s.id}`,
+          contentType: 'image/jpeg',
+          url: `https://example.com/${s.id}.jpg`,
+          source: 'canvas' as const,
+        }));
+      const combined = [...uploads, ...canvasAttachments].slice(0, 50);
+      // Referential equality shortcut
+      if (
+        combined.length === currentAttachments.length &&
+        combined.every(
+          (a, i) =>
+            a.id === currentAttachments[i].id &&
+            a.url === currentAttachments[i].url
+        )
+      ) {
+        return currentAttachments;
+      }
+      return combined;
+    },
+    resizeImageToDataUrl: vi.fn(),
+  };
+});
+
+// Now import the component under test
+import { ChatFooterForm } from '@/app/[locale]/(canvas)/canvas/[id]/_components/chat-footer-form';
+
+// ---------------------------------------------------------------------------
+// i18n messages
+// ---------------------------------------------------------------------------
+const mockMessages = {
+  Canvas: {
+    chat: {
+      placeholder: 'Ask Gazai-chan...',
+      stopGeneration: 'Stop generation',
+      imageAttachment: {
+        addImage: 'Add image',
+        removeImage: 'Remove',
+        maxImagesReached: 'Maximum of {max} images',
+        invalidFileType: 'Invalid file type',
+        tooManyImages:
+          'Remove {excess} image(s) to send. Max {max} allowed.',
+      },
+    },
+  },
+};
+
+// ---------------------------------------------------------------------------
+// Helpers
+// ---------------------------------------------------------------------------
+const defaultProps = {
+  input: '',
+  handleInputChange: vi.fn(),
+  onSubmit: vi.fn(),
+  isDisabled: false,
+  isProcessing: false,
+  onStop: vi.fn(),
+};
+
+function renderForm(props: Partial<Parameters<typeof ChatFooterForm>[0]> = {}) {
+  return render(
+    <NextIntlClientProvider locale="en" messages={mockMessages}>
+      <ChatFooterForm {...defaultProps} {...props} />
+    </NextIntlClientProvider>
+  );
+}
+
+/**
+ * Set the canvas selection so the component's useEffect auto-syncs attachments.
+ * Call inside act() to flush React state updates.
+ */
+function setCanvasSelection(imageIds: string[]) {
+  mockSelected = imageIds.map((id) => ({ id, type: 'image' }));
+  mockGetState.mockReturnValue({
+    selection: { selected: mockSelected },
+  });
+}
+
+// ---------------------------------------------------------------------------
+// Tests
+// ---------------------------------------------------------------------------
+describe('ChatFooterForm - Submit Prevention on Excess Images', () => {
+  beforeEach(() => {
+    vi.clearAllMocks();
+    vi.useFakeTimers();
+    mockSelected = [];
+    mockCanvasObjects = [];
+  });
+
+  afterEach(() => {
+    vi.useRealTimers();
+  });
+
+  it('send button is enabled when input has text and no excess images', () => {
+    renderForm({ input: 'hello', maxModelImages: 16 });
+
+    // The submit button is an icon-only button (Send icon) with type="submit"
+    const allButtons = screen.getAllByRole('button');
+    const sendButton = allButtons.find((b) => b.getAttribute('type') === 'submit');
+    expect(sendButton).toBeDefined();
+    expect(sendButton).not.toBeDisabled();
+  });
+
+  it('send button is disabled when attachments exceed maxModelImages', async () => {
+    // Render with maxModelImages=3
+    renderForm({ input: 'hello', maxModelImages: 3 });
+
+    // Simulate selecting 5 canvas images
+    act(() => {
+      setCanvasSelection(['img-1', 'img-2', 'img-3', 'img-4', 'img-5']);
+    });
+
+    // Advance past the 150ms debounce in the component's useEffect
+    act(() => {
+      vi.advanceTimersByTime(200);
+    });
+
+    // Verify attachments synced (5 images)
+    const attachmentArea = screen.getByTestId('attachment-area');
+    expect(attachmentArea.getAttribute('data-count')).toBe('5');
+
+    // The submit button should be DISABLED because 5 > maxModelImages (3)
+    // This test should FAIL in the RED phase: the component doesn't check
+    // maxModelImages in canSubmit yet.
+    const allButtons = screen.getAllByRole('button');
+    const sendButton = allButtons.find((b) => b.getAttribute('type') === 'submit');
+    expect(sendButton).toBeDefined();
+    expect(sendButton).toBeDisabled();
+  });
+
+  it('send button is enabled when maxModelImages is not provided (backwards compat)', async () => {
+    // No maxModelImages prop — unlimited
+    renderForm({ input: 'hello' });
+
+    // Simulate selecting 20 images (within UI limit of 50)
+    const ids = Array.from({ length: 20 }, (_, i) => `img-${i + 1}`);
+    act(() => {
+      setCanvasSelection(ids);
+    });
+
+    act(() => {
+      vi.advanceTimersByTime(200);
+    });
+
+    const attachmentArea = screen.getByTestId('attachment-area');
+    expect(attachmentArea.getAttribute('data-count')).toBe('20');
+
+    // With no maxModelImages, the button should remain enabled
+    const allButtons = screen.getAllByRole('button');
+    const sendButton = allButtons.find((b) => b.getAttribute('type') === 'submit');
+    expect(sendButton).toBeDefined();
+    expect(sendButton).not.toBeDisabled();
+  });
+
+  it('paperclip button is enabled when above model limit but below UI limit', async () => {
+    renderForm({ input: '', maxModelImages: 16 });
+
+    // Select 20 images — above model limit (16), below UI limit (50)
+    const ids = Array.from({ length: 20 }, (_, i) => `img-${i + 1}`);
+    act(() => {
+      setCanvasSelection(ids);
+    });
+
+    act(() => {
+      vi.advanceTimersByTime(200);
+    });
+
+    const attachmentArea = screen.getByTestId('attachment-area');
+    expect(attachmentArea.getAttribute('data-count')).toBe('20');
+
+    // The paperclip button checks MAX_CHAT_ATTACHMENT_UI_LIMIT (50), not maxModelImages
+    // So it should still be enabled with 20 attachments
+    const allButtons = screen.getAllByRole('button');
+    const paperclipButton = allButtons.find(
+      (b) =>
+        b.getAttribute('type') === 'button' &&
+        b.getAttribute('title') === 'Add image'
+    );
+    expect(paperclipButton).toBeDefined();
+    expect(paperclipButton).not.toBeDisabled();
+  });
+
+  it('send button is enabled when attachments equal maxModelImages exactly', async () => {
+    renderForm({ input: 'hello', maxModelImages: 3 });
+
+    // Select exactly 3 images = maxModelImages
+    act(() => {
+      setCanvasSelection(['img-1', 'img-2', 'img-3']);
+    });
+
+    act(() => {
+      vi.advanceTimersByTime(200);
+    });
+
+    const attachmentArea = screen.getByTestId('attachment-area');
+    expect(attachmentArea.getAttribute('data-count')).toBe('3');
+
+    // Exactly at the limit should be allowed
+    const allButtons = screen.getAllByRole('button');
+    const sendButton = allButtons.find((b) => b.getAttribute('type') === 'submit');
+    expect(sendButton).toBeDefined();
+    expect(sendButton).not.toBeDisabled();
+  });
+});
