+import { describe, it, expect, vi, beforeAll } from 'vitest';
+// eslint-disable-next-line import/named -- false positive: screen is exported from @testing-library/react
+import { render, screen } from '@testing-library/react';
+
+import { ChatImageAttachmentArea } from '@/app/[locale]/(canvas)/canvas/[id]/_components/chat-image-attachment-area';
+import type { ChatAttachment } from '@/lib/chat-image-utils';
+
+// Polyfill ResizeObserver for jsdom
+beforeAll(() => {
+  global.ResizeObserver = class ResizeObserver {
+    observe() {}
+    unobserve() {}
+    disconnect() {}
+  };
+});
+
+// Mock next-intl with parameter interpolation support
+vi.mock('next-intl', () => ({
+  useTranslations: () => (key: string, params?: Record<string, unknown>) => {
+    if (key === 'imageAttachment.tooManyImages') {
+      return `Remove ${params?.excess} image(s) to send. Max ${params?.max} allowed.`;
+    }
+    return key;
+  },
+}));
+
+// Mock lucide-react icons to simple elements
+vi.mock('lucide-react', () => ({
+  ChevronLeft: () => <span data-testid="chevron-left" />,
+  ChevronRight: () => <span data-testid="chevron-right" />,
+  X: () => <span data-testid="x-icon" />,
+}));
+
+/** Helper to create N mock ChatAttachment objects */
+function createMockAttachments(count: number): ChatAttachment[] {
+  return Array.from({ length: count }, (_, i) => ({
+    id: `attachment-${i + 1}`,
+    name: `Image ${i + 1}`,
+    contentType: 'image/jpeg',
+    url: `https://example.com/image-${i + 1}.jpg`,
+    source: 'canvas' as const,
+  }));
+}
+
+describe('ChatImageAttachmentArea', () => {
+  const noop = vi.fn();
+
+  it('renders all badges with normal styling when maxModelImages is undefined', () => {
+    const attachments = createMockAttachments(5);
+
+    const { container } = render(
+      <ChatImageAttachmentArea attachments={attachments} onRemove={noop} />
+    );
+
+    // Each badge is the numbered overlay div inside the image container
+    // The badge divs contain the index number text (1, 2, 3, etc.)
+    const badges = container.querySelectorAll(
+      '[class*="bg-black/60"]'
+    );
+    expect(badges.length).toBe(5);
+
+    // None should have destructive styling
+    const destructiveBadges = container.querySelectorAll(
+      '[class*="bg-destructive"]'
+    );
+    expect(destructiveBadges.length).toBe(0);
+  });
+
+  it('renders all badges with normal styling when count <= maxModelImages', () => {
+    const attachments = createMockAttachments(5);
+
+    const { container } = render(
+      <ChatImageAttachmentArea
+        attachments={attachments}
+        onRemove={noop}
+        maxModelImages={10}
+      />
+    );
+
+    // All 5 badges should have normal bg-black/60 styling
+    const normalBadges = container.querySelectorAll(
+      '[class*="bg-black/60"]'
+    );
+    expect(normalBadges.length).toBe(5);
+
+    // None should have destructive styling
+    const destructiveBadges = container.querySelectorAll(
+      '[class*="bg-destructive"]'
+    );
+    expect(destructiveBadges.length).toBe(0);
+  });
+
+  it('renders red badges on images exceeding maxModelImages', () => {
+    const attachments = createMockAttachments(5);
+
+    const { container } = render(
+      <ChatImageAttachmentArea
+        attachments={attachments}
+        onRemove={noop}
+        maxModelImages={3}
+      />
+    );
+
+    // Badges 1-3 should have normal bg-black/60 styling
+    const normalBadges = container.querySelectorAll(
+      '[class*="bg-black/60"]'
+    );
+    expect(normalBadges.length).toBe(3);
+
+    // Badges 4-5 should have bg-destructive styling (red)
+    const destructiveBadges = container.querySelectorAll(
+      '[class*="bg-destructive"]'
+    );
+    expect(destructiveBadges.length).toBe(2);
+
+    // Image containers 4-5 should have border-destructive class
+    const destructiveBorders = container.querySelectorAll(
+      '[class*="border-destructive"]'
+    );
+    expect(destructiveBorders.length).toBe(2);
+  });
+
+  it('shows warning text when excess images exist', () => {
+    const attachments = createMockAttachments(5);
+
+    render(
+      <ChatImageAttachmentArea
+        attachments={attachments}
+        onRemove={noop}
+        maxModelImages={3}
+      />
+    );
+
+    // Warning text should be visible with the correct excess and max values
+    expect(
+      screen.getByText('Remove 2 image(s) to send. Max 3 allowed.')
+    ).toBeInTheDocument();
+  });
+
+  it('does not show warning when count <= maxModelImages', () => {
+    const attachments = createMockAttachments(3);
+
+    render(
+      <ChatImageAttachmentArea
+        attachments={attachments}
+        onRemove={noop}
+        maxModelImages={5}
+      />
+    );
+
+    // No warning text should be present
+    expect(
+      screen.queryByText(/Remove.*image\(s\) to send/)
+    ).not.toBeInTheDocument();
+  });
+});
