+import { describe, it, expect, vi, beforeEach } from 'vitest';
+
+import type { ChatAttachment } from '@/lib/chat-image-utils';
+import { resolveReferenceImageIds } from '@/lib/chat-image-utils';
+import type { CanvasObject, ImageObject } from '@/components/canvas/types';
+
+// Mock the S3 upload utility
+vi.mock('@/utils/client/image', () => ({
+  uploadImageBase64DirectToS3: vi.fn()
+}));
+
+import { uploadImageBase64DirectToS3 } from '@/utils/client/image';
+
+const mockedUpload = vi.mocked(uploadImageBase64DirectToS3);
+
+// ---------------------------------------------------------------------------
+// Helpers to build test fixtures
+// ---------------------------------------------------------------------------
+
+function makeCanvasAttachment(
+  overrides: Partial<ChatAttachment> & { id: string }
+): ChatAttachment {
+  return {
+    name: 'Canvas image',
+    contentType: 'image/jpeg',
+    url: 'https://cdn.example.com/image.jpg',
+    source: 'canvas',
+    ...overrides
+  };
+}
+
+function makeUploadAttachment(
+  overrides: Partial<ChatAttachment> & { id: string }
+): ChatAttachment {
+  return {
+    name: 'uploaded-file.png',
+    contentType: 'image/png',
+    url: 'data:image/png;base64,iVBORw0KGgo=',
+    source: 'upload',
+    ...overrides
+  };
+}
+
+function makeImageObject(
+  overrides: Partial<ImageObject> & { id: string }
+): ImageObject {
+  return {
+    type: 'image',
+    position: { x: 0, y: 0 },
+    width: 512,
+    height: 512,
+    src: 'https://cdn.example.com/image.jpg',
+    ...overrides
+  };
+}
+
+// ---------------------------------------------------------------------------
+// Tests
+// ---------------------------------------------------------------------------
+
+describe('resolveReferenceImageIds', () => {
+  beforeEach(() => {
+    vi.clearAllMocks();
+  });
+
+  // Test 1: Canvas attachment with imageIds resolves to first imageId
+  it('resolves canvas attachment to database image ID from imageIds[0]', async () => {
+    const attachment = makeCanvasAttachment({ id: 'canvas-obj-1' });
+    const canvasObjects: CanvasObject[] = [
+      makeImageObject({ id: 'canvas-obj-1', imageIds: ['db-id-123'] })
+    ];
+
+    const result = await resolveReferenceImageIds([attachment], canvasObjects);
+
+    expect(result).toEqual(['db-id-123']);
+  });
+
+  // Test 2: Canvas attachment with only imageId (no imageIds) resolves correctly
+  it('resolves canvas attachment from legacy imageId field', async () => {
+    const attachment = makeCanvasAttachment({ id: 'canvas-obj-2' });
+    const canvasObjects: CanvasObject[] = [
+      makeImageObject({
+        id:
